void CHARACTER::MountVnum(DWORD vnum)
{
	if (m_dwMountVnum == vnum)
		return;

	if (IsPC()) // MT2009_PLUS_RELIC_V1 (mount): the relic's lines of mounting / dismounting (playerbot_relikty.cpp)
	{
		void Mt2009RelicOnMount(LPCHARACTER ch, bool bMount);
		if (!m_dwMountVnum && vnum)
			Mt2009RelicOnMount(this, true);
		else if (m_dwMountVnum && !vnum)
			Mt2009RelicOnMount(this, false);
	}

// MT2009_PLUS_RELIC_V1 (remove): a relic leaves its page
else if (m_bWindow == INVENTORY && CHARACTER::Mt2009RelicIsCell(m_wCell))
	pOwner->SetItem(TItemPos(INVENTORY, m_wCell), NULL);
// MT2009_PLUS_ADDEQ_V1 (remove): an item of the inactive equipment page's store leaves the store

// MT2009_PLUS_RELIC_V1 (update): a relic page's item is never sent ("relikt_state" tells the client)
if (GetWindow() == INVENTORY && CHARACTER::Mt2009RelicIsCell(m_wCell))
	return;

// MT2009_PLUS_ADDEQ_V1 (update): the inactive equipment page's store is never sent

	dam = Bonus67Damage(this, pAttacker, (int) type, dam);
}

if (pAttacker) // MT2009_PLUS_RELIC_V1 (damage): the relic lines a blow starts (playerbot_relikty.cpp)
{
	int Mt2009RelicOnDamage(LPCHARACTER pkVictim, LPCHARACTER pkAttacker, int iType, int iDam);
	dam = Mt2009RelicOnDamage(this, pAttacker, (int) type, dam);
}

if (GetHP() <= 0 && IsPC()) // MT2009_PLUS_RELIC_V1 (no death): "Unikniecie smierci" - 30% HP back instead of the death
{
	bool Mt2009RelicNoDeath(LPCHARACTER ch, LPCHARACTER pkAttacker);
	if (Mt2009RelicNoDeath(this, pAttacker))
		return false;
}

if (GetHP() <= 0)
{
	Stun();

	m_SkillUseInfo[dwVnum].dwNextSkillUsableTime = Bonus67SkillCooldown(this, dwVnum, m_SkillUseInfo[dwVnum].dwNextSkillUsableTime);
}

if (false == m_bDisableCooltime) // MT2009_PLUS_RELIC_V1 (skill reset): "Reset umiejetnosci" - every skill's cooldown over
{
	bool Mt2009RelicSkillReset(LPCHARACTER ch, unsigned int dwVnum);
	void Mt2009RelicCooltimeEnd(LPCHARACTER ch, int iSkill);
	if (Mt2009RelicSkillReset(this, dwVnum))
	{
		for (std::map<int, TSkillUseInfo>::iterator itRelic = m_SkillUseInfo.begin(); itRelic != m_SkillUseInfo.end(); ++itRelic)
		{
			itRelic->second.dwNextSkillUsableTime = 0;
			Mt2009RelicCooltimeEnd(this, itRelic->first);
		}
	}
}

